function deepGet(obj, path) {
  if (path === '') return obj;
  const parts = String(path).split('.');
  let cur = obj;
  for (let i = 0; i < parts.length; i++) {
    if (cur == null) return undefined;
    cur = cur[parts[i]];
  }
  return cur;
}
```

Thinking: The user wants a JavaScript function uniquePreserve(arr) that returns a new array of unique primitive values, keeping the first occurrence (case-sensitive). Do not mutate arr.


```javascript
function uniquePreserve(arr) {
  const seen = new Set();
  const result = [];
  for (const item of arr) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}
```

Thinking: The user wants a JavaScript function formatBytes(n) that formats bytes into human-readable format.


```javascript
function formatBytes(n) {
  const units = ['B', 'KB', 'MB', 'GB'];
  let i = 0;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i++;
  }
  const s = Number.isInteger(n) ? String(n) : n.toFixed(1);
  return s + ' ' + units[i];
}
```

