```javascript
function groupBy(arr, key) {
  const result = {};
  for (const obj of arr) {
    const k = obj[key];
    if (!Object.prototype.hasOwnProperty.call(result, k)) {
      result[k] = [];
    }
    result[k].push(obj);
  }
  return result;
}
